                cbs_service_curves[port] = flow['payload'] / flow['periodicity']
    return cbs_service_curves

# Calculate WCD
def calculate_wcd(flow, cbs_service_curve, send_slope, route):
    wcd = 0
    for i in range(len(route)):
        if route[i] == flow['destination']:
            wcd += send_slope[i] * cbs_service_curve[i]
    return wcd

# Main function
def main():
    egress_ports = map_egress_port_queues(topology, flows, route)
    send_slopes = compute_send_slope(egress_ports, flows)
    cbs_service_curves = derive_cbs_service_curve(egress_ports, flows)
    arrival_curves = [construct_arrival_curve(periodicity, flow) for flow in flows.values()]
    for flow in flows.values():
        wcd = calculate_wcd(flow, send_slopes, send_slopes, route)
        print(f"Flow {flow['flow_number']}: WCD = {wcd} μs")

# Confidence score
def calculate_confidence(flow, cbs_service_curve, send_slope, route):
    confidence = 1
    for i in range(len(route)):
        if route[i] == flow['destination']:
            confidence *= send_slope[i] / cbs_service_curve[i]
    return confidence

# Output JSON
def output_json(flow_profile, wcd_us, reason, confidence):
    output = {
        "flow_profile": flow_profile,
        "WCD_us": wcd_us,
        "reason": reason,
        "confidence": confidence
    }
    return json.dumps(output, indent=4)

